function New-Case {
  param(
    [string]$Id,
    [string]$Title,
    [string]$Area,
    [string]$Type,
    [string]$Priority,
    [string[]]$Preconditions,
    [string[]]$Steps,
    [string[]]$Expected,
    [hashtable]$References
  )
  [ordered]@{
    id = $Id
    title = $Title
    area = $Area
    type = $Type
    priority = $Priority
    preconditions = $Preconditions
    steps = $Steps
    expected_results = $Expected
    references = $References
  }
}

