function Get-Counts {
  param([object[]]$Items,[string[]]$Order)
  $result = [ordered]@{}
  foreach ($name in $Order) {
    $count = @($Items | Where-Object { $_ -eq $name }).Count
    if ($count -gt 0) { $result[$name] = $count }
  }
  $result
}

